"use client";

import { CheckSquare, ChevronDown, ChevronUp, Copy, FileUp, GripVertical, ListChecks, Plus, TextCursorInput, Trash2, X } from "lucide-react";
import { useState } from "react";
import type { CheckoutField, CheckoutFieldType } from "@/lib/checkout/custom-fields";

const TYPES: { value: CheckoutFieldType; label: string; detail: string; Icon: typeof TextCursorInput }[] = [
  { value: "text", label: "Text", detail: "Name, wording or instructions", Icon: TextCursorInput },
  { value: "select", label: "Select one", detail: "One choice from a list", Icon: ListChecks },
  { value: "multiselect", label: "Select multiple", detail: "Several choices", Icon: CheckSquare },
  { value: "checklist", label: "Checklist", detail: "Confirm multiple items", Icon: CheckSquare },
  { value: "upload", label: "Upload", detail: "Reference image or document", Icon: FileUp },
];
const needsOptions = (type: CheckoutFieldType) => type === "select" || type === "multiselect" || type === "checklist";

export default function CheckoutFieldsBuilder({ initialFields = [] }: { initialFields?: CheckoutField[] }) {
  const [fields, setFields] = useState(initialFields);
  const [openId, setOpenId] = useState(initialFields[0]?.id ?? "");
  const update = (id: string, patch: Partial<CheckoutField>) => setFields((rows) => rows.map((row) => row.id === id ? { ...row, ...patch } : row));
  const move = (index: number, direction: -1 | 1) => setFields((rows) => { const next = [...rows]; const target = index + direction; if (target < 0 || target >= next.length) return rows; [next[index], next[target]] = [next[target]!, next[index]!]; return next; });
  const addField = (type: CheckoutFieldType = "text") => { const row = { id: crypto.randomUUID(), label: "", type, required: false, options: needsOptions(type) ? ["Option 1"] : [] }; setFields((rows) => [...rows, row]); setOpenId(row.id); };
  return <section className="overflow-hidden rounded-[24px] border border-orange-100 bg-white shadow-[0_16px_42px_rgba(28,28,26,0.08)]">
    <input type="hidden" name="checkoutFields" value={JSON.stringify(fields)} />
    <div className="bg-[radial-gradient(circle_at_top_right,rgba(232,130,12,.28),transparent_35%),linear-gradient(135deg,#211c19,#41271b)] px-5 py-5 text-white sm:px-6"><p className="text-[10px] font-bold uppercase tracking-[.2em] text-orange-200">Optional form builder</p><h2 className="mt-2 text-lg font-black">Questions before checkout</h2><p className="mt-1 max-w-2xl text-xs leading-5 text-white/65">Collect personalization, sizing, reference files, preferences or confirmations specifically for this product.</p></div>
    <div className="p-4 sm:p-6"><div className="grid grid-cols-2 gap-2 sm:grid-cols-5">{TYPES.map(({ value, label, Icon }) => <button key={value} type="button" onClick={() => addField(value)} className="group flex min-h-20 flex-col items-center justify-center gap-1.5 rounded-2xl border border-zinc-200 bg-zinc-50 px-2 text-center transition hover:-translate-y-0.5 hover:border-orange-200 hover:bg-orange-50 hover:shadow-md"><Icon className="size-5 text-[#D4450A]" /><span className="text-[11px] font-bold text-zinc-800">{label}</span></button>)}</div>
      <div className="mt-5 space-y-3">{fields.length === 0 ? <button type="button" onClick={() => addField()} className="flex min-h-28 w-full flex-col items-center justify-center rounded-2xl border-2 border-dashed border-zinc-200 bg-zinc-50 text-center transition hover:border-orange-300 hover:bg-orange-50"><Plus className="size-6 text-[#D4450A]" /><span className="mt-2 text-sm font-bold text-zinc-800">Add your first question</span><span className="mt-1 text-xs text-zinc-500">Customers will see it before paying.</span></button> : fields.map((field, index) => { const meta = TYPES.find((type) => type.value === field.type)!; const expanded = openId === field.id; return <article key={field.id} className="overflow-hidden rounded-2xl border border-zinc-200 bg-white shadow-sm"><div className="flex min-h-14 items-center gap-2 px-3"><GripVertical className="size-4 shrink-0 text-zinc-300" /><button type="button" onClick={() => setOpenId(expanded ? "" : field.id)} className="flex min-w-0 flex-1 items-center gap-3 text-left"><span className="flex size-9 shrink-0 items-center justify-center rounded-xl bg-orange-50 text-[#D4450A]"><meta.Icon className="size-4" /></span><span className="min-w-0"><strong className="block truncate text-sm text-zinc-900">{field.label || `Untitled ${meta.label.toLowerCase()} question`}</strong><span className="text-[10px] text-zinc-400">{meta.label}{field.required ? " · Required" : " · Optional"}</span></span></button><div className="flex items-center gap-1"><button type="button" onClick={() => move(index, -1)} disabled={index === 0} aria-label="Move question up" className="flex size-8 items-center justify-center rounded-lg text-zinc-400 hover:bg-zinc-100 disabled:opacity-25"><ChevronUp className="size-4" /></button><button type="button" onClick={() => move(index, 1)} disabled={index === fields.length - 1} aria-label="Move question down" className="flex size-8 items-center justify-center rounded-lg text-zinc-400 hover:bg-zinc-100 disabled:opacity-25"><ChevronDown className="size-4" /></button><button type="button" onClick={() => setOpenId(expanded ? "" : field.id)} className="flex size-8 items-center justify-center rounded-lg text-zinc-400"><ChevronDown className={`size-4 transition ${expanded ? "rotate-180" : ""}`} /></button></div></div>{expanded ? <div className="border-t border-zinc-100 bg-zinc-50/70 p-4"><div className="grid gap-3 sm:grid-cols-[1fr_180px]"><label className="text-xs font-bold text-zinc-600">Question label<input value={field.label} autoFocus onChange={(e) => update(field.id, { label: e.target.value })} placeholder="Example: What name should we print?" className="mt-1.5 min-h-11 w-full rounded-xl border border-zinc-200 bg-white px-3 text-sm font-medium text-zinc-900 outline-none focus:border-[#D4450A] focus:ring-4 focus:ring-orange-500/10" /></label><label className="text-xs font-bold text-zinc-600">Answer type<select value={field.type} onChange={(e) => { const type = e.target.value as CheckoutFieldType; update(field.id, { type, options: needsOptions(type) && field.options.length === 0 ? ["Option 1"] : field.options }); }} className="mt-1.5 min-h-11 w-full rounded-xl border border-zinc-200 bg-white px-3 text-sm">{TYPES.map((type) => <option key={type.value} value={type.value}>{type.label}</option>)}</select></label></div>{needsOptions(field.type) ? <div className="mt-4"><p className="text-xs font-bold text-zinc-600">Choices</p><div className="mt-2 space-y-2">{field.options.map((option, optionIndex) => <div key={`${field.id}-${optionIndex}`} className="flex gap-2"><input value={option} onChange={(e) => update(field.id, { options: field.options.map((item, i) => i === optionIndex ? e.target.value : item) })} className="min-h-10 min-w-0 flex-1 rounded-xl border border-zinc-200 bg-white px-3 text-sm outline-none focus:border-[#D4450A]" /><button type="button" onClick={() => update(field.id, { options: field.options.filter((_, i) => i !== optionIndex) })} aria-label="Remove option" className="flex size-10 items-center justify-center rounded-xl border border-zinc-200 bg-white text-zinc-400 hover:text-red-600"><X className="size-4" /></button></div>)}<button type="button" onClick={() => update(field.id, { options: [...field.options, `Option ${field.options.length + 1}`] })} className="inline-flex min-h-10 items-center gap-1.5 rounded-xl border border-orange-200 bg-orange-50 px-3 text-xs font-bold text-[#D4450A]"><Plus className="size-3.5" />Add choice</button></div></div> : null}<div className="mt-4 flex flex-wrap items-center justify-between gap-3 border-t border-zinc-200 pt-4"><label className="inline-flex min-h-10 items-center gap-2 rounded-xl bg-white px-3 text-xs font-bold text-zinc-700 ring-1 ring-zinc-200"><input type="checkbox" checked={field.required} onChange={(e) => update(field.id, { required: e.target.checked })} className="size-4 accent-[#D4450A]" />Required</label><div className="flex gap-2"><button type="button" onClick={() => { const copy = { ...field, id: crypto.randomUUID(), label: field.label ? `${field.label} (copy)` : "" }; setFields((rows) => [...rows.slice(0, index + 1), copy, ...rows.slice(index + 1)]); setOpenId(copy.id); }} className="inline-flex min-h-10 items-center gap-1.5 rounded-xl border border-zinc-200 bg-white px-3 text-xs font-bold text-zinc-600"><Copy className="size-3.5" />Duplicate</button><button type="button" onClick={() => setFields((rows) => rows.filter((row) => row.id !== field.id))} className="inline-flex min-h-10 items-center gap-1.5 rounded-xl border border-red-100 bg-red-50 px-3 text-xs font-bold text-red-600"><Trash2 className="size-3.5" />Delete</button></div></div><div className="mt-4 rounded-xl border border-dashed border-zinc-200 bg-white p-3"><p className="text-[10px] font-bold uppercase tracking-wider text-zinc-400">Customer preview</p><p className="mt-2 text-xs font-semibold text-zinc-800">{field.label || "Your question"}{field.required ? <span className="text-[#D4450A]"> *</span> : null}</p><div className="mt-2 min-h-10 rounded-lg border border-zinc-200 bg-zinc-50" /></div></div> : null}</article>; })}</div>
    </div>
  </section>;
}
